items.a:
SELECT ProductName
FROM Products
WHERE ProductName LIKE '%Choco%';

SELECT CompanyName
FROM Customers
WHERE CompanyName LIKE 'A%';

SELECT ProductName
FROM Products
WHERE ProductName LIKE '%berry';

SELECT CompanyName
FROM Suppliers
WHERE CompanyName LIKE '%Food%';

SELECT ProductName
FROM Products
WHERE UnitPrice BETWEEN 10 AND 50;

SELECT ProductName
FROM Products
WHERE UnitPrice < 20 OR UnitPrice > 100;

SELECT ProductName, UnitPrice
FROM Products
WHERE CAST(FLOOR(UnitPrice) AS VARCHAR(10)) NOT LIKE '%0%';

SELECT FirstName, LastName
FROM Employees
WHERE City = 'Seattle' AND Title = 'Sales Representative';

SELECT CategoryID, MAX(UnitsInStock) AS MaxStock
FROM Products
GROUP BY CategoryID;

SELECT SupplierID, MIN(UnitsInStock) AS MinStock
FROM Products
GROUP BY SupplierID;

SELECT TOP 10 ProductName, UnitPrice
FROM Products
ORDER BY UnitPrice DESC;

SELECT OrderID, SUM(Discount) AS TotalDiscount
FROM [Order Details]
GROUP BY OrderID;

SELECT Country, COUNT(CustomerID) AS CustomerCount
FROM Customers
GROUP BY Country;

SELECT DATEPART(MONTH, OrderDate) AS OrderMonth, COUNT(OrderID) AS OrdersCount
FROM Orders
GROUP BY DATEPART(MONTH, OrderDate);

SELECT ProductName, UnitPrice
FROM Products
ORDER BY UnitPrice ASC;

SELECT ProductName, UnitPrice
FROM Products
ORDER BY UnitPrice DESC;

SELECT OrderID, OrderDate
FROM Orders
ORDER BY OrderDate ASC;

SELECT CompanyName
FROM Customers
ORDER BY CompanyName ASC;

SELECT CategoryID, ProductName, UnitPrice
FROM Products
ORDER BY CategoryID, UnitPrice DESC;

SELECT ProductName, CategoryName
FROM Products
INNER JOIN Categories ON Products.CategoryID = Categories.CategoryID;

SELECT o.OrderID, c.CompanyName
FROM Orders o
INNER JOIN Customers c ON o.CustomerID = c.CustomerID;

SELECT od.OrderID, p.ProductName, od.Quantity
FROM [Order Details] od
INNER JOIN Products p ON od.ProductID = p.ProductID;

SELECT s.CompanyName, p.ProductName
FROM Suppliers s
INNER JOIN Products p ON s.SupplierID = p.SupplierID;

SELECT p.ProductName, od.OrderID
FROM [Order Details] od
INNER JOIN Products p ON od.ProductID = p.ProductID;

SELECT e.FirstName, e.LastName, o.OrderID
FROM Orders o
INNER JOIN Employees e ON o.EmployeeID = e.EmployeeID;

SELECT ProductName, UnitPrice
FROM Products
WHERE UnitPrice > (SELECT AVG(UnitPrice) FROM Products);

SELECT ProductName
FROM Products
WHERE ProductID NOT IN (SELECT ProductID FROM [Order Details]);

SELECT ProductName
FROM Products
WHERE UnitPrice > (SELECT UnitPrice FROM Products WHERE ProductName = 'Chai');
